import * as React from "react";
import { Link } from "react-router-dom";
import { Inbox } from "lucide-react";

import { cn } from "@/lib/utils";

// The "never a blank table" pattern: icon + title + message + optional CTA.
// Two CTA shapes: pass `action` (any node) for full control, or the
// actionLabel + actionTo / onAction convenience props for a standard
// link / button styled like the app's primary violet action.
const EmptyState = React.forwardRef(
  (
    {
      icon: Icon = Inbox,
      title = "Nothing here yet",
      message,
      action,
      actionLabel,
      actionTo,
      onAction,
      compact = false,
      className,
      ...props
    },
    ref
  ) => {
    const cta =
      action ||
      (actionLabel && actionTo ? (
        <Link
          to={actionTo}
          className="mt-3 inline-flex min-h-9 items-center gap-1.5 rounded-xl bg-violet-600 px-4 text-sm font-semibold text-white hover:bg-violet-700"
        >
          {actionLabel}
        </Link>
      ) : actionLabel && onAction ? (
        <button
          type="button"
          onClick={onAction}
          className="mt-3 inline-flex min-h-9 items-center gap-1.5 rounded-xl bg-violet-600 px-4 text-sm font-semibold text-white hover:bg-violet-700"
        >
          {actionLabel}
        </button>
      ) : null);
    return (
      <div
        ref={ref}
        className={cn(
          "flex flex-col items-center justify-center px-6 text-center text-slate-500 dark:text-slate-400",
          compact ? "py-8" : "py-16",
          className
        )}
        {...props}
      >
        {Icon && <Icon className="mb-2 h-8 w-8 text-slate-300 dark:text-slate-600" />}
        <div className="text-sm font-semibold text-slate-700 dark:text-slate-200">{title}</div>
        {message && <p className="mt-0.5 max-w-sm text-xs text-slate-400 dark:text-slate-500">{message}</p>}
        {cta}
      </div>
    );
  }
);
EmptyState.displayName = "EmptyState";

export { EmptyState };

import * as React from "react";
import { Link } from "react-router-dom";

import { cn } from "@/lib/utils";
import { TONE_TEXT_CLASSES } from "./statusTones";

// Metric tile row: [{ label, value, tone?, hint?, to?, icon? }].
// `to` makes the tile a react-router link; tone tints the value using the
// shared tone text classes (statusTones.js). Responsive 2 -> 5 columns.
const KpiStrip = React.forwardRef(({ tiles = [], className, ...props }, ref) => {
  const visible = (Array.isArray(tiles) ? tiles : []).filter(Boolean);
  if (!visible.length) return null;
  return (
    <div
      ref={ref}
      className={cn(
        "mb-3 grid grid-cols-2 gap-2 sm:grid-cols-3 lg:grid-cols-5",
        className
      )}
      {...props}
    >
      {visible.map((tile, i) => {
        const Icon = tile.icon;
        const body = (
          <>
            <div className="flex items-center justify-between gap-2">
              <span className="truncate text-[11px] font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">
                {tile.label}
              </span>
              {Icon && <Icon className="h-4 w-4 shrink-0 text-slate-400 dark:text-slate-500" />}
            </div>
            <div
              className={cn(
                "mt-0.5 truncate text-xl font-bold text-slate-900 dark:text-slate-100",
                tile.tone && TONE_TEXT_CLASSES[tile.tone]
              )}
            >
              {tile.value ?? "\u2014"}
            </div>
            {tile.hint && (
              <div className="mt-0.5 truncate text-xs text-slate-400 dark:text-slate-500">
                {tile.hint}
              </div>
            )}
          </>
        );
        const tileCls = cn(
          "rounded-xl border border-slate-200 bg-white px-3 py-2.5 dark:border-slate-700 dark:bg-slate-900",
          tile.to && "transition-colors hover:border-violet-300 hover:bg-violet-50/40 dark:hover:bg-slate-800/60",
          tile.className
        );
        return tile.to ? (
          <Link key={tile.key ?? i} to={tile.to} className={tileCls}>
            {body}
          </Link>
        ) : (
          <div key={tile.key ?? i} className={tileCls}>
            {body}
          </div>
        );
      })}
    </div>
  );
});
KpiStrip.displayName = "KpiStrip";

export { KpiStrip };

import * as React from "react";
import { Search } from "lucide-react";

import { cn } from "@/lib/utils";

// Filter row with a fixed control order -- every list page lays its controls
// out the same way, so callers only supply the pieces they actually have:
//
//   [search] [children = primary selects] [presets] [views] [pageSize] [actions]
//
// Each named slot accepts a node (or array). Slots not passed simply collapse.
// Styled defaults below (FilterSearchInput / FilterSelect / FilterField) carry
// the shared input vocabulary so callers don't re-type the class string.
const FilterBar = React.forwardRef(
  ({ search, presets, views, pageSize, actions, className, children, ...props }, ref) => (
    <div
      ref={ref}
      className={cn(
        "mb-3 flex flex-wrap items-center gap-2 rounded-xl border border-slate-200 bg-slate-50/60 p-2 dark:border-slate-700 dark:bg-slate-800/40",
        className
      )}
      {...props}
    >
      {search}
      {children}
      {presets}
      {views}
      {pageSize}
      {actions && <div className="flex items-center gap-2">{actions}</div>}
    </div>
  )
);
FilterBar.displayName = "FilterBar";

// Shared input styles -- the PurchaseOrders/Invoices `inputCls` vocabulary.
const filterInputCls =
  "min-h-10 w-full rounded-xl border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 focus:border-violet-400 focus:outline-none dark:border-slate-600 dark:bg-slate-800 dark:text-slate-100";

// Search input with the leading Search icon, sized to grow in the bar.
// Ref lands on the <input>; wrap in FilterField for a labelled layout.
const FilterSearchInput = React.forwardRef(
  ({ className, containerClassName, ...props }, ref) => (
    <div className={cn("relative min-w-52 flex-1", containerClassName)}>
      <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
      <input
        ref={ref}
        type="search"
        className={cn(filterInputCls, "pl-9", className)}
        {...props}
      />
    </div>
  )
);
FilterSearchInput.displayName = "FilterSearchInput";

// Styled <select> matching FilterSearchInput. Pass options as children.
const FilterSelect = React.forwardRef(({ className, children, ...props }, ref) => (
  <select ref={ref} className={cn(filterInputCls, "w-auto", className)} {...props}>
    {children}
  </select>
));
FilterSelect.displayName = "FilterSelect";

// Label + control wrapper for the labelled-filter layout the queue pages use
// ("STATUS v"). Wrap any kit input/select: <FilterField label="Status"><FilterSelect/></FilterField>
const FilterField = React.forwardRef(({ label, className, children, ...props }, ref) => (
  <label ref={ref} className={cn("flex flex-col gap-0.5", className)} {...props}>
    {label && (
      <span className="text-[11px] font-semibold uppercase tracking-wide text-slate-500 dark:text-slate-400">
        {label}
      </span>
    )}
    {children}
  </label>
));
FilterField.displayName = "FilterField";

export { FilterBar, FilterSearchInput, FilterSelect, FilterField, filterInputCls };

import * as React from "react";
import { Link } from "react-router-dom";

import { cn } from "@/lib/utils";
import { recordHref } from "./recordRoutes";

// Typed record deep-link. The kind -> route map lives in recordRoutes.js:
//   <RecordLink kind="estimate" id={est.id}>Q-1042</RecordLink>
// renders <Link to="/EstimateDetail?id=...">. When the id is blank or the
// kind is unknown it degrades to a <span> -- never a broken href.
const RecordLink = React.forwardRef(
  ({ kind, id, children, className, ...props }, ref) => {
    const href = recordHref(kind, id);
    const text = children ?? String(id ?? "").trim() ?? "";
    if (!href) {
      return (
        <span ref={ref} className={cn("text-slate-500 dark:text-slate-400", className)} {...props}>
          {text}
        </span>
      );
    }
    return (
      <Link
        ref={ref}
        to={href}
        className={cn("text-sky-700 hover:underline dark:text-sky-400", className)}
        {...props}
      >
        {text}
      </Link>
    );
  }
);
RecordLink.displayName = "RecordLink";

export { RecordLink };

import * as React from "react";
import { Link } from "react-router-dom";

import { cn } from "@/lib/utils";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";

// Standalone lifecycle trail: [{ label, to? }] where the last item renders
// as the current page. Items without `to` render as static text -- handy for
// non-navigable lifecycle steps (e.g. ["Estimate", "Sent", "Approved"]).
const BreadcrumbBar = React.forwardRef(({ items = [], className, ...props }, ref) => {
  const trail = (Array.isArray(items) ? items : []).filter(
    (item) => item && String(item.label ?? "").trim() !== ""
  );
  if (!trail.length) return null;
  return (
    <Breadcrumb ref={ref} className={className} {...props}>
      <BreadcrumbList className="flex-nowrap gap-1.5 text-xs sm:gap-2">
        {trail.map((item, i) => {
          const last = i === trail.length - 1;
          return (
            <React.Fragment key={`${item.label}-${i}`}>
              {i > 0 && <BreadcrumbSeparator />}
              <BreadcrumbItem>
                {last ? (
                  <BreadcrumbPage className="max-w-[220px] truncate">
                    {item.label}
                  </BreadcrumbPage>
                ) : item.to ? (
                  <BreadcrumbLink asChild className="max-w-[220px] truncate">
                    <Link to={item.to}>{item.label}</Link>
                  </BreadcrumbLink>
                ) : (
                  <span className="max-w-[220px] truncate">{item.label}</span>
                )}
              </BreadcrumbItem>
            </React.Fragment>
          );
        })}
      </BreadcrumbList>
    </Breadcrumb>
  );
});
BreadcrumbBar.displayName = "BreadcrumbBar";

export { BreadcrumbBar };

import { createContext, useContext, useEffect, useRef, useState, useCallback } from "react";
import { base44 } from "@/api/base44Client";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogDescription } from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Loader2, LogIn, Eye, AlertCircle } from "lucide-react";

const TOKEN_KEY = "sss_session_token";
const ADMIN_UNLOCKED_KEY = "adminUnlocked";
const ADMIN_CAPABILITY_KEY = "adminSettingsCapability";
const ADMIN_CAPABILITY_EXPIRES_KEY = "adminSettingsCapabilityExpires";

export function getSessionToken() {
  try { return localStorage.getItem(TOKEN_KEY) || ""; } catch { return ""; }
}

// Mirrors the verified session user outside React so non-hook call sites
// (entity loaders, role checks inside load callbacks) can resolve the same
// AuthorizedEmail identity without a network round-trip.
let lastSessionUser = null;
export function getSessionUser() {
  return lastSessionUser;
}

// A staff-facing read can be rejected as unauthenticated while this tab still
// holds a signed-in identity: the token was cleared in another tab, browser
// storage was evicted, or a password reset revoked the session. Loaders only
// see a raw 401, so rejections are reported here and resolved once by the
// session layer — reverifying the stored token, and only dropping a session
// that is genuinely gone (which reopens sign-in). Failures here never replace
// the original request error.
let sessionRejectionListener = null;
export function notifySessionRejected() {
  try {
    sessionRejectionListener?.();
  } catch {
    // Recovery is best-effort; the caller keeps its own error handling.
  }
}

export function clearAdminSettingsAuthorization() {
  try {
    sessionStorage.removeItem(ADMIN_UNLOCKED_KEY);
    sessionStorage.removeItem(ADMIN_CAPABILITY_KEY);
    sessionStorage.removeItem(ADMIN_CAPABILITY_EXPIRES_KEY);
  } catch {}
}

export function getStoredAdminSettingsCapability() {
  try {
    const capability = String(sessionStorage.getItem(ADMIN_CAPABILITY_KEY) || "").trim();
    const expiresAt = Date.parse(String(sessionStorage.getItem(ADMIN_CAPABILITY_EXPIRES_KEY) || ""));
    if (capability && Number.isFinite(expiresAt) && expiresAt > Date.now()) return capability;
  } catch {}
  clearAdminSettingsAuthorization();
  return "";
}

// Read-only: the stored capability's expiry timestamp (ms) so callers can
// schedule a re-lock exactly at expiry. Returns null when nothing usable is
// stored; unlike getStoredAdminSettingsCapability it never mutates storage.
export function getStoredAdminSettingsCapabilityExpiry() {
  try {
    const capability = String(sessionStorage.getItem(ADMIN_CAPABILITY_KEY) || "").trim();
    const expiresAt = Date.parse(String(sessionStorage.getItem(ADMIN_CAPABILITY_EXPIRES_KEY) || ""));
    if (capability && Number.isFinite(expiresAt)) return expiresAt;
  } catch {}
  return null;
}

export function hasStoredAdminSettingsAuthorization() {
  try {
    return sessionStorage.getItem(ADMIN_UNLOCKED_KEY) === "true" && !!getStoredAdminSettingsCapability();
  } catch {
    return false;
  }
}

export function storeAdminSettingsAuthorization(capability, expiresAt) {
  sessionStorage.setItem(ADMIN_UNLOCKED_KEY, "true");
  sessionStorage.setItem(ADMIN_CAPABILITY_KEY, capability);
  sessionStorage.setItem(ADMIN_CAPABILITY_EXPIRES_KEY, expiresAt);
}

// The Time Clock kiosk page is guest-facing: app-level Sign In dialogs must
// never appear there on their own (auto-pop on mount or after a sign-out).
const isTimeClockKioskPath = () => {
  try {
    const path = String(window.location.pathname || "").replace(/\/+$/, "").toLowerCase();
    return path === "/timeclock";
  } catch {
    return false;
  }
};

const AuthContext = createContext(null);

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used inside AuthProvider");
  return ctx;
};

export function AuthProvider({ children }) {
  const [currentUser, setCurrentUserState] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [showLogin, setShowLogin] = useState(false);
  const [browseOnly, setBrowseOnly] = useState(false);

  const setCurrentUser = useCallback((user) => {
    lastSessionUser = user || null;
    setCurrentUserState(user || null);
  }, []);

  // Restore session from stored token
  const restoreSession = useCallback(async () => {
    const token = localStorage.getItem(TOKEN_KEY);
    if (!token) {
      clearAdminSettingsAuthorization();
      setIsLoading(false);
      return;
    }
    try {
      const res = await base44.functions.invoke("verifySession", { token });
      const data = res?.data || res;
      if (data?.valid && data.user) {
        setCurrentUser(data.user);
      } else if (data?.valid === false) {
        localStorage.removeItem(TOKEN_KEY);
        clearAdminSettingsAuthorization();
        setCurrentUser(null);
      }
    } catch (error) {
      // A temporary service failure is not session revocation. Keep the token
      // for the next verification, but do not grant access without verification.
      if ([401, 409].includes(Number(error?.response?.status ?? error?.status))) {
        localStorage.removeItem(TOKEN_KEY);
        clearAdminSettingsAuthorization();
        setCurrentUser(null);
      }
    }
    setIsLoading(false);
  }, [setCurrentUser]);

  useEffect(() => {
    restoreSession();
  }, [restoreSession]);

  // Resolve a rejected read once per wave of 401s. The token is reverified
  // rather than trusted or blindly discarded: only a session that is actually
  // gone ends here — a transient service failure keeps it so the next load can
  // recover without a pointless re-sign-in.
  const sessionRecheckInFlight = useRef(false);
  const resolveSessionRejection = useCallback(async () => {
    if (sessionRecheckInFlight.current) return;
    // Guests hold no identity to recover; their reads are expected to be refused.
    if (!getSessionUser()) return;
    sessionRecheckInFlight.current = true;
    const endSession = () => {
      localStorage.removeItem(TOKEN_KEY);
      clearAdminSettingsAuthorization();
      setCurrentUser(null);
      setBrowseOnly(false);
    };
    try {
      const token = getSessionToken();
      if (!token) {
        endSession();
        return;
      }
      const res = await base44.functions.invoke("verifySession", { token });
      const data = res?.data || res;
      if (data?.valid && data.user) {
        setCurrentUser(data.user);
        return;
      }
      endSession();
    } catch (error) {
      const status = Number(error?.response?.status ?? error?.status ?? error?.originalError?.response?.status);
      if (status === 401 || status === 409) endSession();
    } finally {
      sessionRecheckInFlight.current = false;
    }
  }, [setCurrentUser]);

  useEffect(() => {
    sessionRejectionListener = resolveSessionRejection;
    return () => {
      if (sessionRejectionListener === resolveSessionRejection) sessionRejectionListener = null;
    };
  }, [resolveSessionRejection]);

  const logout = useCallback(() => {
    // Server-side revoke: invalidate the session token so it can't be reused
    // from a copied/localStorage token. Fire-and-forget — logout proceeds
    // locally even if the network call fails.
    const token = localStorage.getItem(TOKEN_KEY);
    if (token) {
      base44.functions.invoke("verifySession", { token, action: "logout" }).catch(() => {});
    }
    localStorage.removeItem(TOKEN_KEY);
    clearAdminSettingsAuthorization();
    setCurrentUser(null);
    setBrowseOnly(false);
    setShowLogin(!isTimeClockKioskPath());
  }, [setCurrentUser]);

  const loginWithCredentials = useCallback(async (username, password) => {
    try {
      const res = await base44.functions.invoke("verifyLogin", { username, password });
      const data = res?.data || res;
      if (data?.success && data.token) {
        clearAdminSettingsAuthorization();
        localStorage.setItem(TOKEN_KEY, data.token);
        setCurrentUser(data.user);
        setBrowseOnly(false);
        setShowLogin(false);
        return { success: true };
      }
      return { success: false, error: data?.error || "Invalid username or password" };
    } catch (err) {
      const status = err?.response?.status ?? err?.status;
      const apiError = err?.response?.data?.error;
      // A 5xx (or a request that never completed) means sign-in was never
      // evaluated — say so plainly instead of showing a raw server error name.
      if (typeof status !== "number" || status >= 500) {
        return { success: false, error: "Sign in hit a temporary server problem. Please try again." };
      }
      return { success: false, error: apiError || "Invalid username or password" };
    }
  }, [setCurrentUser]);

  const getUserFirstName = useCallback(() => {
    if (!currentUser?.full_name) return "";
    return currentUser.full_name.split(" ")[0];
  }, [currentUser]);

  // Show login dialog automatically when not authenticated and not in browse
  // mode — except on the Time Clock kiosk, where guests must be left alone.
  // Explicit Sign In clicks still open it through showLoginDialog().
  useEffect(() => {
    if (!isLoading && !currentUser && !browseOnly && !isTimeClockKioskPath()) {
      setShowLogin(true);
    }
  }, [isLoading, currentUser, browseOnly]);

  // Gate used by pages/components: if not logged in, pop the login dialog and
  // return false so the caller can abort the action.
  const requireLogin = useCallback(() => {
    if (currentUser) return true;
    setBrowseOnly(false);
    setShowLogin(true);
    return false;
  }, [currentUser]);

  const value = {
    currentUser,
    sessionToken: currentUser ? (localStorage.getItem(TOKEN_KEY) || "") : "",
    isRegistered: !!currentUser,
    isLoading,
    logout,
    loginWithCredentials,
    getUserFirstName,
    showLoginDialog: () => { setBrowseOnly(false); setShowLogin(true); },
    requireLogin,
  };

  if (isLoading) {
    return (
      <div className="fixed inset-0 flex items-center justify-center">
        <Loader2 className="w-8 h-8 animate-spin text-purple-500" />
      </div>
    );
  }

  return (
    <AuthContext.Provider value={value}>
      {children}
      <LoginDialog
        open={showLogin && !currentUser}
        onLogin={loginWithCredentials}
      />
    </AuthContext.Provider>
  );
}

function LoginDialog({ open, onLogin }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [submitting, setSubmitting] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    setSubmitting(true);
    const res = await onLogin(username.trim(), password);
    setSubmitting(false);
    if (!res.success) setError(res.error);
    else {
      setUsername("");
      setPassword("");
    }
  };

  return (
    <Dialog open={open} onOpenChange={(isOpen) => {
      // A backdrop tap or browser Back must not silently switch staff into guest mode.
      // The separate browse button below is the only intentional dismissal path.
      if (isOpen) return;
    }}>
      <DialogContent
        className="sm:max-w-md"
        onInteractOutside={(event) => event.preventDefault()}
        onEscapeKeyDown={(event) => event.preventDefault()}
      >
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            <LogIn className="w-5 h-5 text-purple-600" /> Sign In
          </DialogTitle>
          <DialogDescription>
            Enter your username and password to access the Sign Shop Workflow.
          </DialogDescription>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-3 pt-2">
          <div>
            <Label htmlFor="login-username">Username</Label>
            <Input
              id="login-username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              autoComplete="username"
              autoFocus
              required
            />
          </div>
          <div>
            <Label htmlFor="login-password">Password</Label>
            <Input
              id="login-password"
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              autoComplete="current-password"
              required
            />
          </div>

          {error && (
            <div className="flex items-start gap-2 p-2 bg-red-50 border border-red-200 rounded text-sm text-red-700">
              <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" />
              <span>{error}</span>
            </div>
          )}

          <Button type="submit" disabled={submitting} className="w-full bg-purple-600 hover:bg-purple-700">
            {submitting ? <Loader2 className="w-4 h-4 animate-spin" /> : "Sign In"}
          </Button>
        </form>


      </DialogContent>
    </Dialog>
  );
}
